from fastapi import Body, FastAPI
from fastapi.testclient import TestClient
app = FastAPI()

# Plain Body field: the body itself is a string with min_length=5
@app.post('/items-plain')
def create_plain(name: str = Body(min_length=5)):
    return {'name': name}

# With embed=True: body is an object containing the field
@app.post('/items-embed')
def create_embed(name: str = Body(min_length=5, embed=True)):
    return {'name': name}

client = TestClient(app)
print('=== plain: short body ===')
r = client.post('/items-plain', json='hi')
